"""PSLE-style items for sci-energy-heat-temp (file sci-heat-temp.json), all tiers (round sci-fill-heat-temp-2026-11-20)."""
from fillkit import add, table, graph, lint
from figs_heat import thermometer, touching, bath, blocks

SUB, FILE = "sci-energy-heat-temp", "sci-heat-temp.json"
HT, FT, RD = "sci-pat-heat-temperature", "sci-pat-fair-test-design", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
def tb(h, r, w, c): return lambda: table(h, r, w, c)
D = "°C"
def TH(v, **k): return lambda: thermometer(v, caption="A thermometer", **k)

# ---------------- basic ----------------
q("ht-001", B, 1, HT, "Which of the following is a source of heat?", "The Sun", [W("A block of ice", "wrong-source", "Ice is cold. It takes in heat."), W("A glass of cold milk", "wrong-source", "Cold milk is not a source of heat."), W("A cold metal spoon", "wrong-source", "A cold spoon does not give out heat.")], ["The Sun gives out a lot of heat."], None)
q("ht-002", B, 1, HT, "Which of the following gives out heat when electricity flows through it?", "A toaster", [W("A wooden spoon", "wrong-source", "A wooden spoon does not give out heat."), W("A glass of water", "wrong-source", "Water does not give out heat when electricity is not used on it."), W("A rubber ball", "wrong-source", "A rubber ball does not give out heat.")], ["A toaster changes electrical energy into heat."], None)
q("ht-003", B, 3, HT, "Which instrument is used to measure temperature?", "A thermometer", [W("A ruler", "wrong-tool", "A ruler measures length."), W("A balance", "wrong-tool", "A balance measures mass."), W("A measuring cylinder", "wrong-tool", "A measuring cylinder measures volume.")], ["Temperature is measured with a thermometer."], None)
