q("ht-005", B, 2, HT, "Temperature is a measure of how ____ an object is.", "hot or cold", [W("heavy or light", "wrong-idea", "Mass tells us how heavy an object is."), W("big or small", "wrong-idea", "Size is not temperature."), W("fast or slow", "wrong-idea", "Speed is not temperature.")], ["Temperature tells how hot or cold something is."], None)
q("ht-006", B, 2, HT, "Heat is a form of ____.", "energy", [W("force", "wrong-idea", "Heat is not a push or a pull."), W("matter", "wrong-idea", "Heat has no mass and takes up no space."), W("material", "wrong-idea", "Heat is not a material.")], ["Heat is a form of energy."], None)
q("ht-007", B, 4, HT, "A cup of hot tea is left on a table in a cool room. Which way does heat flow?", "From the tea to the surroundings", [W("From the surroundings to the tea", "reversed", "Heat flows from hot to cold."), W("From the table to the tea", "reversed", "The tea is hotter than the table."), W("Heat does not flow", "wrong-idea", "There is a difference in temperature, so heat flows.")], ["Heat flows from the hotter tea to the cooler surroundings."], None)
q("ht-008", B, 3, HT, "Ali puts a thermometer into a cup of water. What is the reading on the thermometer?", "24 " + D, [W("22 " + D, "misread", "Count the small marks again from 20."), W("26 " + D, "misread", "The liquid is below the 26 mark."), W("14 " + D, "misread", "The liquid is above the 20 mark.")], ["The liquid is two small marks above 20, so it reads 24 " + D + "."], TH(24))
q("ht-009", B, 3, HT, "A thermometer is used to measure the temperature of a bowl of soup. What is the reading?", "36 " + D, [W("34 " + D, "misread", "The liquid is above the 34 mark."), W("38 " + D, "misread", "The liquid has not reached the 38 mark."), W("26 " + D, "misread", "The liquid is above the 30 mark.")], ["The liquid is three small marks above 30, so it reads 36 " + D + "."], TH(36))
q("ht-010", B, 3, HT, "Mei Ling measures the temperature of the classroom air in the morning. What does the thermometer read?", "18 " + D, [W("16 " + D, "misread", "The liquid is above 16."), W("22 " + D, "misread", "The liquid is below 20."), W("28 " + D, "misread", "The liquid is below 20.")], ["The liquid is just below 20, at the second mark below it, so it reads 18 " + D + "."], TH(18))
q("ht-011", B, 3, HT, "A thermometer is placed in a glass of warm milk. What is its reading?", "42 " + D, [W("40 " + D, "misread", "The liquid is above the 40 mark."), W("44 " + D, "misread", "The liquid has not reached 44."), W("32 " + D, "misread", "The liquid is above 40.")], ["The liquid is one small mark above 40, so it reads 42 " + D + "."], TH(42))
q("ht-012", B, 3, HT, "A thermometer is placed in the water of a fish tank. What is the reading?", "12 " + D, [W("10 " + D, "misread", "The liquid is above 10."), W("14 " + D, "misread", "The liquid is below 14."), W("22 " + D, "misread", "The liquid is below 20.")], ["The liquid is one small mark above 10, so it reads 12 " + D + "."], TH(12))
q("ht-013", B, 4, HT, "Blocks P and Q are in contact as shown. Which block will gain heat?", "Q", [W("P", "reversed", "P is hotter, so it loses heat."), W("Both P and Q", "wrong-idea", "Only the cooler block gains heat."), W("Neither P nor Q", "wrong-idea", "Heat flows because their temperatures differ.")], ["Heat flows from the hotter P to the cooler Q."], lambda: touching("P", "80 " + D, "Q", "30 " + D, "Two blocks in contact"))
