q("ht-015", B, 4, HT, "A piece of ice at 0 " + D + " is placed in a room at 28 " + D + ". Which way does heat flow?", "From the room to the ice", [W("From the ice to the room", "reversed", "The room is hotter than the ice."), W("Heat does not flow", "wrong-idea", "They have different temperatures, so heat flows."), W("Cold flows from the ice to the room", "wrong-idea", "Heat flows. There is no flow of cold.")], ["Heat flows from the hotter room to the colder ice."], None)
