q("ht-016", B, 2, HT, "The table shows the temperatures of four objects. Which object is the hottest?", "R", [W("P", "wrong-reading", "P is cooler than R."), W("Q", "wrong-reading", "Q is the coldest."), W("S", "wrong-reading", "S is cooler than R.")], ["62 " + D + " is the highest temperature."], TT)
q("ht-017", B, 2, HT, "Using the table, which object is the coldest?", "Q", [W("P", "wrong-reading", "P is hotter than Q."), W("R", "wrong-reading", "R is the hottest."), W("S", "wrong-reading", "S is hotter than Q.")], ["5 " + D + " is the lowest temperature."], TT)
q("ht-018", B, 4, HT, "Why does a piece of ice feel cold when we hold it in our hand?", "Heat flows from our hand to the ice", [W("Cold flows from the ice to our hand", "wrong-idea", "Heat flows. There is no flow of cold."), W("Heat flows from the ice to our hand", "reversed", "The hand is hotter than the ice."), W("The ice makes our hand lose mass", "wrong-idea", "This has nothing to do with heat.")], ["Our hand loses heat to the colder ice."], None)
