q("ht-022", B, 3, HT, "What is the usual temperature of the body of a healthy person?", "About 37 " + D, [W("About 10 " + D, "wrong-reading", "This is far too cold."), W("About 25 " + D, "wrong-reading", "This is room temperature."), W("About 60 " + D, "wrong-reading", "This is far too hot.")], ["A healthy body is at about 37 " + D + "."], None)
q("ht-023", B, 3, HT, "A thermometer is put in a glass of ice water. Which reading is the most likely?", "1 " + D, [W("25 " + D, "wrong-reading", "This is room temperature."), W("37 " + D, "wrong-reading", "This is body temperature."), W("90 " + D, "wrong-reading", "This is very hot water.")], ["Ice water is close to 0 " + D + "."], None)
q("ht-024", B, 3, HT, "Aisha wants to read the temperature of a cup of tea. Which is the best way to read the thermometer?", "Wait for the liquid to stop moving, then read it at eye level", [W("Take it out at once and read it from above", "wrong-method", "The liquid has not settled, and the view from above misreads."), W("Read it as soon as it is put in, from below", "wrong-method", "The liquid is still moving and the view from below misreads."), W("Hold the bulb in her hand while reading", "wrong-method", "Her hand would change the temperature.")], ["Wait until the reading is steady and look straight at the scale."], None)
q("ht-025", B, 4, HT, "A spoon at 20 " + D + " is put into water at 70 " + D + ". What happens to the spoon?", "It gains heat and its temperature rises", [W("It loses heat and its temperature falls", "reversed", "The water is hotter, so the spoon gains heat."), W("Its temperature stays at 20 " + D, "wrong-idea", "Heat flows into it, so the temperature changes."), W("It gains heat and its temperature falls", "wrong-idea", "Gaining heat raises the temperature.")], ["Heat flows from the hot water to the spoon."], None)

