def _apply():
    out = []
    for r in P:
        m = EDIT.get(r[0])
        if m:
            r = list(r)
            if r[5] in m:
                r[5] = m[r[5]]
            r[6] = [(m.get(w[0], w[0]),) + tuple(w[1:]) for w in r[6]]
            r = tuple(r)
        out.append(r)
    return out

if __name__ == "__main__":
    print("added", add(SUB, FILE, _apply()))
    lint(SUB, FILE, "ht-")
